{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?riskTolerance ?timeHorizon
WHERE {
  ?investor a wm:Investor ;
            wm:investorId "INV-1010" .
  OPTIONAL { ?investor wm:riskTolerance ?rtLit . }
  OPTIONAL {
    ?investor wm:hasRiskTolerance ?rtNode .
    ?rtNode rdfs:label ?rtLabel .
  }
  OPTIONAL { ?investor wm:timeHorizon ?thLit . }
  OPTIONAL {
    ?investor wm:hasTimeHorizon ?thNode .
    ?thNode rdfs:label ?thLabel .
  }
  BIND (COALESCE(?rtLit, ?rtLabel) AS ?riskTolerance)
  BIND (COALESCE(?thLit, ?thLabel) AS ?timeHorizon)
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?investmentGoal ?segment
WHERE {
  ?investor a wm:Investor ;
            wm:investorId "INV-1011" .
  OPTIONAL { ?investor wm:segment ?segment . }
  OPTIONAL { ?investor wm:investmentGoal ?investmentGoal . }
  OPTIONAL {
    ?investor wm:hasInvestmentGoal ?ig .
    OPTIONAL { ?ig wm:investmentGoal ?investmentGoal . }
    OPTIONAL { ?ig rdfs:label ?investmentGoal . }
  }
} LIMIT 1"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance "Moderate" .

  ?ph a wm:PortfolioHealth ;
       wm:healthOfInvestor ?inv ;
       wm:riskScore ?riskScore .
  FILTER(?riskScore > 75) .

  ?pholding a wm:PortfolioHolding ;
            wm:heldByInvestor ?inv ;
            wm:investmentType "Equity" .
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance "Conservative" .

  ?ph a wm:PortfolioHealth ;
       wm:investorId ?investorId ;
       wm:diversificationScore ?divScore .
  FILTER(?divScore < 25)

  FILTER EXISTS {
    ?sr a wm:ScenarioRebalancing ;
        wm:investorId ?investorId ;
        wm:scenario "Currency Depreciation" .
  }

  FILTER EXISTS {
    ?goal a wm:InvestmentGoal ;
          wm:investorId ?investorId ;
          wm:shortfall ?sf .
    FILTER(?sf > 0)
  }
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:riskTolerance ?riskTol .
  FILTER(LCASE(?riskTol) = "conservative")

  ?ph a wm:PortfolioHealth ;
      wm:investorId ?investorId ;
      wm:diversificationScore ?divScore .
  FILTER(xsd:decimal(?divScore) < 25)

  ?sr a wm:ScenarioRebalancing ;
      wm:investorId ?investorId ;
      wm:scenario ?scenario .
  FILTER(LCASE(?scenario) = "economic growth")

  ?goal a wm:InvestmentGoal ;
        wm:investorId ?investorId ;
        wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)
}
GROUP BY ?investorId ?investorName"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv rdf:type wm:Investor ;
       wm:riskTolerance "Moderate" ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName .

  ?ph rdf:type wm:PortfolioHealth ;
      wm:healthOfInvestor ?inv ;
      wm:diversificationScore ?divScore .
  FILTER(?divScore < 25)

  ?goal rdf:type wm:InvestmentGoal ;
        wm:belongsToInvestor ?inv ;
        wm:shortfall ?sf .
  FILTER(?sf > 0)

  FILTER EXISTS {
    ?scenario rdf:type wm:MarketScenario ;
              rdfs:label "Bull Market" .
  }
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
