{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?liquidityScore ?allocationPct
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:riskTolerance "Conservative" ;
            wm:hasPortfolioHealth ?ph ;
            wm:hasSectorAllocation ?sa .

  ?ph wm:liquidityScore ?liquidityScore .
  FILTER(?liquidityScore < 25) .

  ?sa wm:sector "Banking" ;
      wm:allocationPct ?allocationPct .
  FILTER(?allocationPct > 0) .
}
GROUP BY ?investorId ?investorName ?liquidityScore ?allocationPct"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?loss_holding_count
WHERE {
  {
    SELECT ?investor ?investorId ?investorName
    WHERE {
      ?investor rdf:type wm:Investor ;
                wm:investorId ?investorId ;
                wm:investorName ?investorName ;
                wm:riskTolerance ?riskTol .
      FILTER(LCASE(STR(?riskTol)) = "moderate")
    }
  }
  {
    SELECT ?investor (MAX(?riskScore) AS ?riskScore)
    WHERE {
      ?ph rdf:type wm:PortfolioHealth ;
          wm:healthOfInvestor ?investor ;
          wm:riskScore ?riskScore .
    }
    GROUP BY ?investor
    HAVING (xsd:decimal(?riskScore) > 75)
  }
  {
    SELECT ?investor (MAX(?shortfall) AS ?shortfall)
    WHERE {
      ?goal rdf:type wm:InvestmentGoal ;
            wm:belongsToInvestor ?investor ;
            wm:shortfall ?shortfall .
    }
    GROUP BY ?investor
    HAVING (xsd:decimal(?shortfall) > 0)
  }
  {
    SELECT ?investor (COUNT(?holding) AS ?loss_holding_count)
    WHERE {
      ?holding rdf:type wm:PortfolioHolding ;
               wm:heldByInvestor ?investor ;
               wm:cost ?cost ;
               wm:currentValue ?curr .
      FILTER(xsd:decimal(?curr) < xsd:decimal(?cost))
    }
    GROUP BY ?investor
    HAVING (COUNT(?holding) > 0)
  }
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:riskTolerance ?riskTol ;
            wm:hasPortfolioHealth ?ph ;
            wm:hasInvestmentGoal ?ig ;
            wm:hasRebalancingAction ?ra .
  FILTER(LCASE(STR(?riskTol)) = "aggressive")
  ?ph wm:riskScore ?riskScore .
  FILTER(xsd:decimal(?riskScore) > 75)
  ?ig wm:shortfall ?shortfall .
  FILTER(xsd:decimal(?shortfall) > 0)
  ?ra wm:action ?action .
  FILTER(LCASE(STR(?action)) = "buy")
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
