{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId ?investorName ?diversificationScore
WHERE {
  ?inv a wm:Investor ;
       wm:investorId ?investorId ;
       wm:investorName ?investorName ;
       wm:riskTolerance ?riskTol ;
       wm:hasPortfolioHealth ?ph .

  ?ph a wm:PortfolioHealth ;
      wm:investorId ?investorId ;
      wm:diversificationScore ?diversificationScore .

  FILTER(LCASE(?riskTol) = "aggressive")
  FILTER(?diversificationScore < 25)
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?investor a wm:Investor ;
            wm:investorId ?investorId ;
            wm:investorName ?investorName ;
            wm:segment ?segment ;
            wm:hasPortfolioHealth ?ph ;
            wm:hasHolding ?holding .

  FILTER(LCASE(STR(?segment)) = "mid cap") .

  ?ph wm:liquidityScore ?liqScore .
  FILTER(?liqScore < 50) .

  ?holding wm:investmentType ?invType .
  FILTER(LCASE(STR(?invType)) = "equity") .
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?investorId ?investorName
WHERE {
  ?inv a wm:Investor .
  ?inv wm:investorId ?investorId .
  ?inv wm:investorName ?investorName .
  ?inv wm:riskTolerance ?rt .
  FILTER(LCASE(?rt) = "conservative") .

  FILTER EXISTS {
    ?inv wm:hasPortfolioHealth ?ph .
    ?ph wm:riskScore ?riskScore .
    FILTER(?riskScore > 50)
  }

  FILTER EXISTS {
    ?inv wm:hasHolding ?hold .
    ?hold wm:investmentType ?invType .
    FILTER(LCASE(?invType) = "corporate bond")
  }

  FILTER EXISTS {
    ?inv wm:hasInvestmentGoal ?goal .
    ?goal wm:shortfall ?shortfall .
    FILTER(?shortfall > 0)
  }
}"}

