{"Q1": "PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX wm: <https://wealth.example.org/ontology/>

SELECT ?goalId ?shortfall ?label ?investmentGoal ?targetAmount ?currentValue ?progressPct ?timeToGoalMonths ?avgAnnualReturnPct ?avgSharpeRatio ?avgVolatilityPct ?stdDevAnnualReturnPct ?avgPostTaxReturnPct ?description ?belongsToInvestor ?investorId ?sourceTable ?hasInvestmentGoalType
WHERE {
  ?ig rdf:type wm:InvestmentGoal .
  OPTIONAL { ?ig wm:goalId ?goalId . }
  OPTIONAL { ?ig wm:shortfall ?shortfall . }
  FILTER (!BOUND(?shortfall))
  OPTIONAL { ?ig rdfs:label ?label . }
  OPTIONAL { ?ig wm:investmentGoal ?investmentGoal . }
  OPTIONAL { ?ig wm:targetAmount ?targetAmount . }
  OPTIONAL { ?ig wm:currentValue ?currentValue . }
  OPTIONAL { ?ig wm:progressPct ?progressPct . }
  OPTIONAL { ?ig wm:timeToGoalMonths ?timeToGoalMonths . }
  OPTIONAL { ?ig wm:avgAnnualReturnPct ?avgAnnualReturnPct . }
  OPTIONAL { ?ig wm:avgSharpeRatio ?avgSharpeRatio . }
  OPTIONAL { ?ig wm:avgVolatilityPct ?avgVolatilityPct . }
  OPTIONAL { ?ig wm:stdDevAnnualReturnPct ?stdDevAnnualReturnPct . }
  OPTIONAL { ?ig wm:avgPostTaxReturnPct ?avgPostTaxReturnPct . }
  OPTIONAL { ?ig wm:description ?description . }
  OPTIONAL { ?ig wm:belongsToInvestor ?belongsToInvestor . }
  OPTIONAL { ?ig wm:investorId ?investorId . }
  OPTIONAL { ?ig wm:sourceTable ?sourceTable . }
  OPTIONAL { ?ig wm:hasInvestmentGoalType ?hasInvestmentGoalType . }
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?cf ?cashFlowId ?source ?amount ?date ?label ?cashFlowOfInvestor ?type ?investorId ?hasCashFlowSource ?sourceTable ?hasCashFlowType ?notes
WHERE {
  ?cf a wm:CashFlow .
  OPTIONAL { ?cf wm:source ?source . }
  FILTER (!BOUND(?source))
  OPTIONAL { ?cf wm:cashFlowId ?cashFlowId . }
  OPTIONAL { ?cf wm:amount ?amount . }
  OPTIONAL { ?cf wm:date ?date . }
  OPTIONAL { ?cf rdfs:label ?label . }
  OPTIONAL { ?cf wm:cashFlowOfInvestor ?cashFlowOfInvestor . }
  OPTIONAL { ?cf wm:type ?type . }
  OPTIONAL { ?cf wm:investorId ?investorId . }
  OPTIONAL { ?cf wm:hasCashFlowSource ?hasCashFlowSource . }
  OPTIONAL { ?cf wm:sourceTable ?sourceTable . }
  OPTIONAL { ?cf wm:hasCashFlowType ?hasCashFlowType . }
  OPTIONAL { ?cf wm:notes ?notes . }
}"}

{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?ra
       ?currentAllocationPct
       ?amount
       ?targetAllocationPct
       ?label
       ?hasRebalancingLogic
       ?rebalanceId
       ?hasRebalancingDecision
       ?investorId
       ?rebalancingActionOfInvestor
       ?action
       ?sourceTable
       ?logic
       ?notes
WHERE {
  ?ra a wm:RebalancingAction .
  FILTER NOT EXISTS { ?ra wm:action ?anyAction . }

  OPTIONAL { ?ra wm:currentAllocationPct ?currentAllocationPct . }
  OPTIONAL { ?ra wm:amount ?amount . }
  OPTIONAL { ?ra wm:targetAllocationPct ?targetAllocationPct . }
  OPTIONAL { ?ra rdfs:label ?label . }
  OPTIONAL { ?ra wm:hasRebalancingLogic ?hasRebalancingLogic . }
  OPTIONAL { ?ra wm:rebalanceId ?rebalanceId . }
  OPTIONAL { ?ra wm:hasRebalancingDecision ?hasRebalancingDecision . }
  OPTIONAL { ?ra wm:investorId ?investorId . }
  OPTIONAL { ?ra wm:rebalancingActionOfInvestor ?rebalancingActionOfInvestor . }
  OPTIONAL { ?ra wm:action ?action . }   # will be unbound due to filter
  OPTIONAL { ?ra wm:sourceTable ?sourceTable . }
  OPTIONAL { ?ra wm:logic ?logic . }
  OPTIONAL { ?ra wm:notes ?notes . }
}"}

