{"Q1": "PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?scenarioRebalanceId ?investorId ?scenario ?label ?triggeredAction ?currentAllocationPct ?newAllocationPct ?rationale ?sourceTable ?affectedAssetsSectors (GROUP_CONCAT(DISTINCT ?affectsAssetOrSector; separator=",") AS ?affectsAssetOrSector) ?hasMarketScenario ?scenarioRebalancingOfInvestor ?hasTriggeredAction
WHERE {
  ?sr a wm:ScenarioRebalancing .
  FILTER NOT EXISTS { ?sr wm:triggeredAction ?any . }
  OPTIONAL { ?sr wm:scenarioRebalanceId ?scenarioRebalanceId . }
  OPTIONAL { ?sr wm:investorId ?investorId . }
  OPTIONAL { ?sr wm:scenario ?scenario . }
  OPTIONAL { ?sr rdfs:label ?label . }
  OPTIONAL { ?sr wm:triggeredAction ?triggeredAction . }
  OPTIONAL { ?sr wm:currentAllocationPct ?currentAllocationPct . }
  OPTIONAL { ?sr wm:newAllocationPct ?newAllocationPct . }
  OPTIONAL { ?sr wm:rationale ?rationale . }
  OPTIONAL { ?sr wm:sourceTable ?sourceTable . }
  OPTIONAL { ?sr wm:affectedAssetsSectors ?affectedAssetsSectors . }
  OPTIONAL { ?sr wm:affectsAssetOrSector ?affectsAssetOrSector . }
  OPTIONAL { ?sr wm:hasMarketScenario ?hasMarketScenario . }
  OPTIONAL { ?sr wm:scenarioRebalancingOfInvestor ?scenarioRebalancingOfInvestor . }
  OPTIONAL { ?sr wm:hasTriggeredAction ?hasTriggeredAction . }
}
GROUP BY ?scenarioRebalanceId ?investorId ?scenario ?label ?triggeredAction ?currentAllocationPct ?newAllocationPct ?rationale ?sourceTable ?affectedAssetsSectors ?hasMarketScenario ?scenarioRebalancingOfInvestor ?hasTriggeredAction"}

