SELECT ?holdingId ?investmentName
WHERE {
  ?holding a wm:PortfolioHolding ;
           wm:heldByInvestor ?investor ;
           wm:holdingId ?holdingId ;
           wm:investmentName ?investmentName .

  {
    ?investor wm:segment ?segLabel .
